import React, { useState } from "react";
import { Link } from "react-router-dom";
import { Menu, X } from "lucide-react";
import { motion } from "framer-motion";

export default function Navbar() {
  const [isOpen, setIsOpen] = useState(false);

  const links = [
    { name: "Home", path: "/" },
    { name: "Interview", path: "/interview" },
    { name: "Feedback", path: "/feedback" },
  ];

  return (
    <motion.nav
      initial={{ y: -60, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.6 }}
      className="bg-gradient-to-r from-blue-600 to-blue-500 shadow-lg text-white sticky top-0 z-50"
    >
      <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
        {/* Brand Logo */}
        <h1 className="text-2xl md:text-3xl font-bold tracking-wide cursor-pointer">
          AI Interview Coach
        </h1>

        {/* Desktop Navigation Links */}
        <div className="hidden md:flex items-center space-x-8">
          {links.map((link) => (
            <Link
              key={link.name}
              to={link.path}
              className="hover:text-blue-200 transition duration-200 font-medium"
            >
              {link.name}
            </Link>
          ))}

          {/* Auth Buttons */}
          <div className="ml-6 flex space-x-4">
            {/* LOGIN */}
            <motion.button
              whileHover={{
                scale: 1.07,
                boxShadow: "0 0 10px rgba(255,255,255,0.5)",
              }}
              whileTap={{ scale: 0.95 }}
              className="px-5 py-2 border-2 border-white rounded-md hover:bg-white hover:text-blue-600 transition font-semibold"
            >
              Login
            </motion.button>

            {/* SIGN UP */}
            <motion.button
              whileHover={{
                scale: 1.07,
                boxShadow: "0 0 20px rgba(59,130,246,0.8)",
              }}
              whileTap={{ scale: 0.95 }}
              className="px-5 py-2 bg-gradient-to-r from-blue-300 via-blue-400 to-blue-600 text-blue-900 font-semibold rounded-md shadow-md hover:shadow-blue-300 transition"
            >
              Sign Up
            </motion.button>
          </div>
        </div>

        {/* Mobile Menu Button */}
        <button
          onClick={() => setIsOpen(!isOpen)}
          className="md:hidden focus:outline-none"
        >
          {isOpen ? <X size={26} /> : <Menu size={26} />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          className="md:hidden bg-blue-500 flex flex-col items-center space-y-4 py-4"
        >
          {links.map((link) => (
            <Link
              key={link.name}
              to={link.path}
              onClick={() => setIsOpen(false)}
              className="hover:text-blue-200 text-lg font-medium transition"
            >
              {link.name}
            </Link>
          ))}

          {/* Auth Buttons (Mobile) */}
          <div className="flex flex-col space-y-3 mt-3">
            <motion.button
              whileHover={{
                scale: 1.05,
                boxShadow: "0 0 10px rgba(255,255,255,0.6)",
              }}
              whileTap={{ scale: 0.95 }}
              className="px-6 py-2 border-2 border-white rounded-md text-white font-semibold hover:bg-white hover:text-blue-600 transition"
            >
              Login
            </motion.button>

            <motion.button
              whileHover={{
                scale: 1.05,
                boxShadow: "0 0 20px rgba(59,130,246,0.8)",
              }}
              whileTap={{ scale: 0.95 }}
              className="px-6 py-2 bg-gradient-to-r from-blue-300 via-blue-400 to-blue-600 text-blue-900 font-semibold rounded-md shadow-md hover:shadow-blue-300 transition"
            >
              Sign Up
            </motion.button>
          </div>
        </motion.div>
      )}
    </motion.nav>
  );
}
